package com.oguzguven.portfolio.settings;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class SiteSettingsService{private final SiteSettingsRepository repository;public SiteSettingsService(SiteSettingsRepository repository){this.repository=repository;}@Transactional(readOnly=true)public SiteSettingsResponse get(){return SiteSettingsResponse.from(repository.findById(1L).orElseThrow());}@Transactional public SiteSettingsResponse update(SiteSettingsRequest request){var value=repository.findById(1L).orElseGet(()->new SiteSettings(request));var normalized=new SiteSettingsRequest(request.siteName(),request.role(),request.browserTitle(),request.metaDescription(),request.siteLanguage(),request.displayYear(),request.projectsYear(),request.technologyYear(),request.cvUrl(),request.cvFileName(),or(request.navWorkLabel(),value.getNavWorkLabel(),"WORK"),or(request.navAboutLabel(),value.getNavAboutLabel(),"ABOUT"),or(request.navExperienceLabel(),value.getNavExperienceLabel(),"EXPERIENCE"),or(request.navContactLabel(),value.getNavContactLabel(),"CONTACT"),or(request.projectsEyebrow(),value.getProjectsEyebrow(),"SELECTED WORK"),or(request.projectsTitle(),value.getProjectsTitle(),"Things I've"),or(request.projectsHighlight(),value.getProjectsHighlight(),"built"),or(request.experienceEyebrow(),value.getExperienceEyebrow(),"EXPERIENCE"),or(request.experienceTitle(),value.getExperienceTitle(),"Where I've"),or(request.experienceHighlight(),value.getExperienceHighlight(),"worked"),or(request.technologyHeading(),value.getTechnologyHeading(),"WHAT I WORK WITH"),or(request.technologyLabel(),value.getTechnologyLabel(),"TECH STACK"));value.update(normalized);return SiteSettingsResponse.from(repository.save(value));}private String or(String next,String current,String fallback){return next==null||next.isBlank()?(current==null||current.isBlank()?fallback:current):next;}}
